import {DB} from './supabase.js';import {$,esc,pageLink} from './ui.js';
export async function renderLogin(){
 const root=$('#app');if(await DB.session()){location.href=pageLink('dashboard');return}
 root.innerHTML=`<div class="login-page"><section class="login-panel"><div class="login-card"><div class="login-brand"><span class="login-logo"><i class="bi bi-mortarboard-fill"></i></span><span>Class Attendance System</span></div><h1>Welcome back</h1><p>Sign in to manage your class attendance.</p>${!DB.configured&&!DB.demo?`<div class="config-warning"><strong>Setup required.</strong> Add your Supabase project URL and anon key in <code>js/config.js</code>, or open the working sample below.</div>`:''}<form id="loginForm"><div class="field"><label for="email">Username / Email</label><div class="input-wrap"><i class="bi bi-person"></i><input class="input" id="email" type="email" autocomplete="username" placeholder="cr@university.edu" required></div></div><div class="field" style="margin-top:15px"><label for="password">Password</label><div class="input-wrap"><i class="bi bi-lock"></i><input class="input" id="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" class="password-toggle" id="showPass" aria-label="Show password"><i class="bi bi-eye"></i></button></div></div><div class="login-options"><label class="check-label"><input type="checkbox" checked> Remember login</label><span>Secure sign-in</span></div><button class="btn btn-primary login-submit" ${!DB.isReady?'disabled':''}><i class="bi bi-shield-lock"></i> Login</button></form>${!DB.configured&&!DB.demo?`<a class="btn btn-soft" style="width:100%;margin-top:12px" href="login.html?demo=1"><i class="bi bi-play-circle"></i> Open interactive demo</a>`:''}<div class="login-help"><i class="bi bi-info-circle"></i> Access is limited to authorized CR and Admin accounts.</div></div></section><section class="login-showcase"><span class="orb one"></span><span class="orb two"></span><div class="showcase-content"><span class="eyebrow"><i class="bi bi-stars"></i> Smarter class administration</span><h2>Attendance,<br>without the paperwork.</h2><p>Mark a full class in seconds, spot attendance risks early, and prepare polished reports whenever you need them.</p><div class="showcase-metrics"><div class="show-metric"><strong>Fast</strong><span>One-tap status marking</span></div><div class="show-metric"><strong>Live</strong><span>Synced across devices</span></div><div class="show-metric"><strong>Clear</strong><span>Actionable class insights</span></div></div></div></section></div>`;
 $('#showPass').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#showPass i').className=`bi ${p.type==='password'?'bi-eye':'bi-eye-slash'}`};
 $('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;b.innerHTML='<i class="bi bi-arrow-repeat"></i> Signing in…';try{await DB.signIn($('#email').value,$('#password').value);location.href=pageLink('dashboard')}catch(err){b.disabled=false;b.innerHTML='<i class="bi bi-shield-lock"></i> Login';let x=$('.login-error');if(!x){x=document.createElement('div');x.className='config-warning login-error';e.target.prepend(x)}x.innerHTML=`<i class="bi bi-exclamation-circle"></i> ${esc(err.message||'Unable to sign in.')}`}}
}
